import asyncio
from sqlalchemy import create_engine, text
from sqlalchemy.ext.asyncio import create_async_engine
base = "app:app@127.0.0.1:5433/app"
for q in ["sslmode=require", "sslmode=require&channel_binding=require", ""]:
    try:
        with create_engine(f"postgresql://{base}?{q}").connect() as c:
            print("psycopg2", q or "(none)", "OK", c.execute(text("select ssl from pg_stat_ssl where pid=pg_backend_pid()")).scalar())
    except Exception as e: print("psycopg2", q or "(none)", "FAIL", type(e).__name__, str(e).splitlines()[0][:90])
async def t(q):
    try:
        e = create_async_engine(f"postgresql+asyncpg://{base}?{q}")
        async with e.connect() as c:
            print("asyncpg", q or "(none)", "OK", (await c.execute(text("select ssl from pg_stat_ssl where pid=pg_backend_pid()"))).scalar())
        await e.dispose()
    except Exception as e: print("asyncpg", q or "(none)", "FAIL", type(e).__name__, str(e).splitlines()[0][:90])
for q in ["ssl=require", "sslmode=require", "sslmode=require&channel_binding=require"]:
    asyncio.run(t(q))
EOF
